def experiment(inputs):
    # Simulate consensus accuracy vs independent accuracy
    # Varying accuracy of 'self' vs 'consensus' across trials
    import random
    results = []
    for _ in range(inputs['trials']):
        consensus_acc = random.uniform(0.5, 0.9)
        self_acc = random.uniform(0.4, 0.95)
        # Decision rule: Trust self if self_acc > consensus_acc
        if self_acc > consensus_acc:
             outcome = 1 if self_acc > random.random() else 0
        else:
             outcome = 1 if consensus_acc > random.random() else 0
        results.append(outcome)
    return {'accuracy': sum(results) / len(results)}

def experiment(inputs):
    # Simulate agent partitioning reasoning resources
    # Vary planning_budget from 10 to 90 percent of total_resources
    # Measure success rate on task completion
    import random
    results = []
    for ratio in [0.1, 0.3, 0.5, 0.7, 0.9]:
        success = 1.0 if random.random() < (1.0 - abs(ratio - 0.5)) else 0.0
        results.append(success)
    return {'measurements': {'accuracy': results}}

def experiment(inputs):
    import random
    params = inputs.get('parameters', {})
    seeds = inputs.get('seeds', [42])
    latency_steps = params.get('latency_steps', [0])
    volatility = params.get('environment_volatility', 0.5)
    results = {}
    for seed in seeds:
        random.seed(seed)
        measurements = []
        for latency in latency_steps:
            failure_rate = (latency * volatility) / 100 + (random.random() * 0.1)
            measurements.append(failure_rate)
        results[str(seed)] = measurements
    return {"measurements": {"failure_rate": results}}

def experiment(inputs):
    import random
    params = inputs.get('parameters', {})
    latency_steps = params.get('latency_steps', [0, 50, 100, 200])
    seeds = inputs.get('seeds', [1, 2, 3])
    results = {}
    for seed in seeds:
        random.seed(seed)
        for step in latency_steps:
            # Simulate drift calculation
            variance = random.random() * (step * 0.001)
            results[f'latency_{step}_seed_{seed}'] = variance
    return {'measurements': {'divergence_variance': list(results.values())}}

def experiment(inputs):
    import random
    seeds = inputs.get('seeds', [1])
    results = {}
    for seed in seeds:
        random.seed(seed)
        results[seed] = [1.0 if random.random() > 0.2 else 0.0]
    return {'measurements': {'accuracy': [1.0]}}

import random

def experiment(inputs):
    trials = inputs.get('trials', 50)
    results = []
    for _ in range(trials):
        # Simulate rigid vs adaptive policy accuracy
        rigid_success = random.random() < 0.65
        adaptive_success = random.random() < 0.85
        results.append(1.0 if adaptive_success else 0.0)
    return {"measurements": {"accuracy": results}}

